// Single source of truth: all authentication credentials and configuration live in this node.
// Edit this object only. Nothing is stored in flow/global context.
var cfg = {
    keycloak: {
        baseUrl: String(env.get("KEYCLOAK_BASE_URL") || "").replace(/\/$/, ""),
        realm: String(env.get("KEYCLOAK_REALM") || ""),
        uiClientId: String(env.get("KEYCLOAK_UI_CLIENT_ID") || ""),
        loginClientId: String(env.get("KEYCLOAK_LOGIN_CLIENT_ID") || ""),
        redirectUri: String(env.get("KEYCLOAK_REDIRECT_URI") || ""),
        adminClientId: String(env.get("KEYCLOAK_ADMIN_CLIENT_ID") || ""),
        adminClientSecret: String(env.get("KEYCLOAK_ADMIN_CLIENT_SECRET") || "")
    },
    oidc: {
        scope: "openid profile email",
        sessionTtlMinutes: 480
    },
    authorization: {
        accessRolePrefix: "facis-access-",
        accessAreas: [
            "localCatalogue",
            "catalogueRegistry",
            "schemaRegistry",
            "adminTools",
            "harvest"
        ],
        permissionsByArea: {
            localCatalogue: [
                "local.catalogue.read"
            ],
            catalogueRegistry: [
                "catalogue.registry.create",
                "catalogue.registry.read",
                "catalogue.registry.update",
                "catalogue.registry.delete"
            ],
            schemaRegistry: [
                "schema.registry.create",
                "schema.registry.read",
                "schema.registry.update",
                "schema.registry.delete"
            ],
            adminTools: [
                "users.create",
                "users.read",
                "users.update",
                "users.delete",
                "roles.create",
                "roles.read",
                "roles.update",
                "roles.delete",
                "audit.read"
            ],
            harvest: [
                "harvest.run.execute",
                "harvest.scope.create",
                "harvest.scope.read",
                "harvest.scope.update",
                "harvest.scope.delete",
                "harvest.lifecycle.configure",
                "harvest.crawling.configure"
            ]
        },
        accessKeysByArea: {
            localCatalogue: "local_catalogue",
            catalogueRegistry: "catalogue_registry",
            schemaRegistry: "schema_registry",
            adminTools: "admin_tools",
            harvest: "harvester"
        }
    },
    collections: {
        sessions: "auth_sessions",
        audit: "dcm_audit_log"
    }
};

cfg.keycloak.baseUrl = String(cfg.keycloak.baseUrl || "").replace(/\/+$/, "");
cfg.keycloak.realm = String(cfg.keycloak.realm || "").trim();
cfg.keycloak.issuer = cfg.keycloak.baseUrl + "/realms/" + encodeURIComponent(cfg.keycloak.realm);

function usesHttp(value) {
    var candidate = String(value || "").toLowerCase();
    return candidate.indexOf("http://") === 0 || candidate.indexOf("https://") === 0;
}

if (!usesHttp(cfg.keycloak.baseUrl) || !usesHttp(cfg.keycloak.redirectUri) || !cfg.keycloak.realm) {
    node.status({ fill: "red", shape: "ring", text: "invalid local configuration" });
    msg.payload = {
        response: {
            action: msg.type || "authentication",
            status: "error",
            error: "auth_configuration_invalid",
            message: "Check the configuration object inside the Auth credentials & configuration manager node."
        }
    };
    return [null, msg];
}

if (!cfg.keycloak.adminClientSecret) {
    node.status({ fill: "yellow", shape: "ring", text: "admin secret missing" });
} else {
    node.status({ fill: "green", shape: "dot", text: "local configuration ready" });
}

// Pass the private configuration only through the current message.
msg._authConfig = cfg;
return [msg, null];

const cfg = msg._authConfig;
if (!cfg) {
  msg.payload = { response: { action: "getOidcConfig", status: "error", error: "auth_configuration_unavailable" } };
  return msg;
}
const issuer = cfg.keycloak.issuer;
msg.payload = { response: {
  action: "getOidcConfig",
  status: "success",
  enabled: true,
  issuer,
  clientId: cfg.keycloak.uiClientId,
  redirectUri: cfg.keycloak.redirectUri,
  scope: cfg.oidc.scope,
  authorizationEndpoint: issuer + "/protocol/openid-connect/auth",
  endSessionEndpoint: issuer + "/protocol/openid-connect/logout"
} };
return msg;

const cfg = msg._authConfig;
const d = msg.data || (msg.payload && msg.payload.data) || {};
const username = String(d.username || "").trim();
const password = String(d.password || "");
delete msg.data;
if (msg.payload && typeof msg.payload === "object") delete msg.payload.data;
if (!cfg) {
  msg.payload = { response: { action: "login", status: "error", error: "auth_configuration_unavailable" } };
  return [null, msg];
}
if (!username || !password) {
  msg.payload = { response: { action: "login", status: "error", error: "missing_credentials", message: "Username and password are required." } };
  return [null, msg];
}
msg._oidc = {
  base: cfg.keycloak.baseUrl,
  realm: cfg.keycloak.realm,
  issuer: cfg.keycloak.issuer,
  clientId: cfg.keycloak.loginClientId,
  step: "passwordToken",
  action: "login"
};
msg.method = "POST";
msg.url = cfg.keycloak.issuer + "/protocol/openid-connect/token";
msg.headers = { "content-type": "application/x-www-form-urlencoded" };
msg.payload = [
  "grant_type=password",
  "client_id=" + encodeURIComponent(cfg.keycloak.loginClientId),
  "username=" + encodeURIComponent(username),
  "password=" + encodeURIComponent(password),
  "scope=" + encodeURIComponent(cfg.oidc.scope)
].join("&");
return [msg, null];

const cfg = msg._authConfig;
const d = msg.data || (msg.payload && msg.payload.data) || {};
if (!cfg) {
  msg.payload = { response: { action: "oidcExchange", status: "error", error: "auth_configuration_unavailable" } };
  return [null, msg];
}
if (!d.code || !d.verifier || !d.nonce || d.redirectUri !== cfg.keycloak.redirectUri) {
  msg.payload = { response: { action: "oidcExchange", status: "error", error: "invalid_oidc_callback", message: "The OIDC callback is incomplete or has an invalid redirect URI." } };
  return [null, msg];
}
msg._oidc = {
  base: cfg.keycloak.baseUrl,
  realm: cfg.keycloak.realm,
  issuer: cfg.keycloak.issuer,
  clientId: cfg.keycloak.uiClientId,
  redirectUri: cfg.keycloak.redirectUri,
  nonce: d.nonce,
  step: "token",
  action: "oidcExchange"
};
msg.method = "POST";
msg.url = cfg.keycloak.issuer + "/protocol/openid-connect/token";
msg.headers = { "content-type": "application/x-www-form-urlencoded" };
msg.payload = [
  "grant_type=authorization_code",
  "client_id=" + encodeURIComponent(cfg.keycloak.uiClientId),
  "code=" + encodeURIComponent(d.code),
  "redirect_uri=" + encodeURIComponent(cfg.keycloak.redirectUri),
  "code_verifier=" + encodeURIComponent(d.verifier)
].join("&");
return [msg, null];

function fail(error, message) {
  const action = (msg._oidc && msg._oidc.action) || "oidcExchange";
  delete msg._oidc;
  delete msg.method; delete msg.url; delete msg.headers; delete msg.statusCode;
  delete msg.responseUrl; delete msg.redirectList; delete msg.retry;
  msg.payload = { response: { action, status: "error", error, message } };
  return [null, null, msg];
}
function decode(token) {
  const parts = String(token || "").split(".");
  if (parts.length !== 3) throw new Error("invalid JWT");
  let value = parts[1].replace(/-/g, "+").replace(/_/g, "/");
  while (value.length % 4) value += "=";
  return JSON.parse(Buffer.from(value, "base64").toString("utf8"));
}
function first(attributes, key, fallback) {
  const value = attributes && attributes[key];
  return Array.isArray(value)
    ? (value[0] === undefined ? fallback : value[0])
    : (value === undefined ? fallback : value);
}
function values(attributes, key) {
  const value = attributes && attributes[key];
  if (Array.isArray(value)) return value;
  return value === undefined || value === null || value === "" ? [] : [value];
}

const cfg = msg._authConfig;
if (!cfg) return fail("auth_configuration_unavailable", "Authentication configuration is unavailable.");

function accessAreaFromRole(name) {
  const value = String(name || "");
  if (!value.startsWith(cfg.authorization.accessRolePrefix)) return null;
  const area = value.slice(cfg.authorization.accessRolePrefix.length);
  return cfg.authorization.accessAreas.includes(area) ? area : null;
}
function areaPermissions(areas) {
  const output = {};
  (areas || []).forEach(area => {
    (cfg.authorization.permissionsByArea[area] || []).forEach(permission => {
      output[permission] = true;
    });
  });
  return Object.keys(output);
}
function accessKeys(areas) {
  const output = (areas || [])
    .map(area => cfg.authorization.accessKeysByArea[area])
    .filter(Boolean);
  if (!output.includes("local_catalogue")) output.unshift("local_catalogue");
  return output;
}

const state = msg._oidc || {};
const body = msg.payload || {};

if (state.step === "passwordToken") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !body.access_token) {
    return fail("invalid_credentials", body.error_description || "Invalid username or password.");
  }
  state.accessToken = body.access_token;
  state.step = "userinfo";
  msg._oidc = state;
  msg.method = "GET";
  msg.url = state.issuer + "/protocol/openid-connect/userinfo";
  msg.headers = { authorization: "Bearer " + body.access_token };
  msg.payload = "";
  return [msg, null, null];
}

if (state.step === "token") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !body.access_token || !body.id_token) {
    return fail("token_exchange_failed", body.error_description || body.error || "Keycloak rejected the authorization code.");
  }
  let idClaims;
  try {
    idClaims = decode(body.id_token);
  } catch (error) {
    return fail("invalid_id_token", "Keycloak returned an invalid ID token.");
  }
  const audience = Array.isArray(idClaims.aud) ? idClaims.aud : [idClaims.aud];
  if (
    idClaims.iss !== state.issuer ||
    idClaims.nonce !== state.nonce ||
    (!audience.includes(state.clientId) && idClaims.azp !== state.clientId) ||
    !idClaims.exp ||
    idClaims.exp <= Math.floor(Date.now() / 1000)
  ) {
    return fail("invalid_id_token", "The Keycloak ID token failed issuer, audience, nonce, or expiry validation.");
  }
  state.accessToken = body.access_token;
  state.idClaims = idClaims;
  state.step = "userinfo";
  msg._oidc = state;
  msg.method = "GET";
  msg.url = state.issuer + "/protocol/openid-connect/userinfo";
  msg.headers = { authorization: "Bearer " + body.access_token };
  msg.payload = "";
  return [msg, null, null];
}

if (state.step === "userinfo") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !body.sub || (state.idClaims && body.sub !== state.idClaims.sub)) {
    return fail("invalid_user_token", "Keycloak could not validate the signed-in user.");
  }
  state.userinfo = body;
  if (!cfg.keycloak.adminClientSecret) {
    return fail("keycloak_backend_not_configured", "KEYCLOAK_ADMIN_CLIENT_SECRET is not configured on Node-RED.");
  }
  state.step = "serviceToken";
  msg._oidc = state;
  msg.method = "POST";
  msg.url = state.issuer + "/protocol/openid-connect/token";
  msg.headers = { "content-type": "application/x-www-form-urlencoded" };
  msg.payload = [
    "grant_type=client_credentials",
    "client_id=" + encodeURIComponent(cfg.keycloak.adminClientId),
    "client_secret=" + encodeURIComponent(cfg.keycloak.adminClientSecret)
  ].join("&");
  return [msg, null, null];
}

if (state.step === "serviceToken") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !body.access_token) {
    return fail("keycloak_backend_auth_failed", body.error_description || "The Keycloak backend client could not authenticate.");
  }
  state.adminToken = body.access_token;
  state.step = "user";
  msg._oidc = state;
  msg.method = "GET";
  msg.url = state.base + "/admin/realms/" + encodeURIComponent(state.realm) + "/users/" + encodeURIComponent(state.userinfo.sub);
  msg.headers = { authorization: "Bearer " + state.adminToken };
  msg.payload = "";
  return [msg, null, null];
}

if (state.step === "user") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !body.id) {
    return fail("account_not_provisioned", "Your Keycloak identity is not provisioned in the FACIS realm.");
  }
  if (body.enabled === false) {
    return fail("account_disabled", "Your account is disabled. Please ask an administrator to activate it.");
  }
  state.user = body;
  state.step = "roles";
  msg._oidc = state;
  msg.method = "GET";
  msg.url = state.base + "/admin/realms/" + encodeURIComponent(state.realm) + "/users/" + encodeURIComponent(body.id) + "/role-mappings/realm/composite";
  msg.headers = { authorization: "Bearer " + state.adminToken };
  msg.payload = "";
  return [msg, null, null];
}

if (state.step === "roles") {
  if (msg.statusCode < 200 || msg.statusCode >= 300 || !Array.isArray(body)) {
    return fail("role_lookup_failed", "Keycloak roles could not be loaded.");
  }
  const attributes = state.user.attributes || {};
  const allRoleRows = body.filter(role =>
    role &&
    role.name &&
    !["offline_access", "uma_authorization"].includes(role.name) &&
    !role.name.startsWith("default-roles-")
  );
  const roleAreas = allRoleRows.map(role => accessAreaFromRole(role.name)).filter(Boolean);
  const applicationRoleRows = allRoleRows.filter(role => !accessAreaFromRole(role.name));
  const roles = applicationRoleRows.map(role => role.name);
  const rolePermissions = [];
  applicationRoleRows.forEach(role => {
    values(role.attributes || {}, "permissions").forEach(permission => {
      if (permission && !rolePermissions.includes(permission)) rolePermissions.push(permission);
    });
  });

  let areas = values(attributes, "accessAreas").filter(area => cfg.authorization.accessAreas.includes(area));
  roleAreas.forEach(area => {
    if (!areas.includes(area)) areas.push(area);
  });
  if (!areas.includes("localCatalogue")) areas.unshift("localCatalogue");

  const expiresAt = first(attributes, "expiresAt", null);
  if (expiresAt && new Date(expiresAt) <= new Date()) {
    return fail("account_expired", "Your account has expired. Contact an administrator.");
  }
  const status = first(attributes, "status", "active");
  if (status === "disabled" || status === "deleted") {
    return fail("account_disabled", "Your account is disabled. Please ask an administrator to activate it.");
  }

  let permissions = [];
  values(attributes, "permissions")
    .concat(rolePermissions)
    .concat(areaPermissions(areas))
    .forEach(permission => {
      if (permission && !permissions.includes(permission)) permissions.push(permission);
    });

  if (roles.includes("admin")) {
    permissions = ["*"];
    areas = cfg.authorization.accessAreas.slice();
  }

  const user = {
    id: state.user.id,
    username: state.user.username || state.userinfo.preferred_username || "",
    email: state.user.email || state.userinfo.email || "",
    role: roles[0] || "viewer",
    roles,
    permissions,
    accessAreas: areas,
    access: accessKeys(areas),
    status,
    expiresAt: expiresAt || null
  };

  const sessionToken = crypto.randomBytes(32).toString("hex");
  msg._oidcResponse = {
    response: {
      action: state.action || "oidcExchange",
      status: "success",
      token: sessionToken,
      user
    }
  };
  msg.collection = cfg.collections.sessions;
  msg.operation = "insertOne";
  msg.payload = {
    token: sessionToken,
    keycloakSubject: state.user.id,
    username: user.username,
    userId: state.user.id,
    user,
    createdAt: new Date().toISOString(),
    expiresAt: new Date(Date.now() + cfg.oidc.sessionTtlMinutes * 60000).toISOString()
  };
  return [null, msg, null];
}

return fail("oidc_state_error", "Unexpected OIDC processing state.");

const cfg = msg._authConfig;
const response = msg._oidcResponse;
const user = response && response.response && response.response.user;
msg.payload = response;
delete msg._oidc; delete msg._oidcResponse; delete msg.collection; delete msg.operation;
delete msg.method; delete msg.url; delete msg.headers; delete msg.statusCode;
delete msg.responseUrl; delete msg.redirectList; delete msg.retry;
const audit = {
  collection: cfg ? cfg.collections.audit : "dcm_audit_log",
  operation: "insertOne",
  payload: {
    timestamp: new Date().toISOString(),
    action: "login.success",
    actor: user ? user.username : "unknown",
    actorId: user ? user.id : null,
    target: user ? user.username : null,
    source: "keycloak"
  }
};
return [msg, audit];

const cfg = msg._authConfig;
const token = (msg.data && msg.data.token) || (msg.auth && msg.auth.userToken) || "";
if (!token) {
  msg.payload = { response: { action: "checkAuth", status: "error", error: "not_authenticated" } };
  return [null, msg];
}
if (!cfg) {
  msg.payload = { response: { action: "checkAuth", status: "error", error: "auth_configuration_unavailable" } };
  return [null, msg];
}
msg._authAction = "checkAuth";
msg.collection = cfg.collections.sessions;
msg.operation = "findOne";
msg.payload = { token };
return [msg, null];

const cfg = msg._authConfig;
const token = (msg.data && msg.data.token) || (msg.auth && msg.auth.userToken) || "";
if (!token) {
  msg.payload = { response: { action: "hydrateSession", status: "error", error: "not_authenticated" } };
  return [null, msg];
}
if (!cfg) {
  msg.payload = { response: { action: "hydrateSession", status: "error", error: "auth_configuration_unavailable" } };
  return [null, msg];
}
msg._authAction = "hydrateSession";
msg.collection = cfg.collections.sessions;
msg.operation = "findOne";
msg.payload = { token };
return [msg, null];

const action = msg._authAction || "checkAuth";
const session = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
if (!session || (session.expiresAt && new Date(session.expiresAt) <= new Date())) {
  msg.payload = { response: { action, status: "error", error: "not_authenticated", message: "Session expired or invalid." } };
} else {
  msg.payload = { response: { action, status: "success", user: session.user } };
}
delete msg._authAction; delete msg.collection; delete msg.operation; return msg;

const cfg = msg._authConfig;
const token = (msg.data && msg.data.token) || (msg.auth && msg.auth.userToken) || "";
if (!token) {
  msg.payload = { response: { action: "logOut", status: "success" } };
  return [null, msg];
}
if (!cfg) {
  msg.payload = { response: { action: "logOut", status: "error", error: "auth_configuration_unavailable" } };
  return [null, msg];
}
msg.collection = cfg.collections.sessions;
msg.operation = "deleteOne";
msg.payload = { token };
return [msg, null];
